"""External signature review controls; generated bytes and command doubles only."""

from __future__ import annotations

import hashlib
import io
import plistlib
import struct
import zipfile

import pytest

from mobile_audit import cms_verification as cms
from mobile_audit import ipa_resource_seal as seals
from mobile_audit.processes import CommandFailure


def _tlv(tag, body):
    assert len(body) < 128
    return bytes([tag, len(body)]) + body


def detached_fixture():
    signed = _tlv(
        0x30,
        _tlv(2, b"\x01") + _tlv(0x31, b"") + _tlv(0x30, _tlv(6, cms.DATA_OID)) + _tlv(0x31, _tlv(0x30, b"")),
    )
    envelope = _tlv(0x30, _tlv(6, cms.SIGNED_DATA_OID) + _tlv(0xA0, signed))
    directory = struct.pack(">II", 0xFADE0C02, 44) + bytes(36)
    cms._detached_signed_data(envelope)
    return envelope, directory


@pytest.mark.parametrize("status", [1, 2, 127])
def test_cmsout_executed_rejection_is_unsupported_not_unavailable(monkeypatch, status):
    envelope, directory = detached_fixture()
    calls = []

    def command(argv, **kwargs):
        calls.append(argv)
        assert "-cmsout" in argv
        raise CommandFailure(argv[0], status)

    monkeypatch.setattr(cms, "command", command)
    result = cms.verify_cms_code_directory(envelope, directory)
    assert len(calls) == 1
    assert result["state"] == "unsupported"
    assert "unavailable" not in result["reason"]
    assert not result["cryptographic_signature_verified"]
    assert not result["app_authenticity_verified"]


@pytest.mark.parametrize(
    "error",
    [
        PermissionError("synthetic denied"),
        ValueError("Command timed out"),
        ValueError("Command output exceeds size limit"),
        FileNotFoundError("synthetic missing"),
    ],
)
def test_cmsout_unavailable_or_incomplete_remains_not_run(monkeypatch, error):
    envelope, directory = detached_fixture()

    def command(*args, **kwargs):
        raise error

    monkeypatch.setattr(cms, "command", command)
    result = cms.verify_cms_code_directory(envelope, directory)
    assert result["state"] == "not-run"
    assert not result["cryptographic_signature_verified"]
    assert not result["app_authenticity_verified"]


def test_verify_child_exit_is_typed_invalid_without_filesystem_guess(monkeypatch):
    envelope, directory = detached_fixture()

    def command(argv, **kwargs):
        if "-cmsout" in argv:
            return envelope
        raise CommandFailure(argv[0], 4)

    monkeypatch.setattr(cms, "command", command)
    result = cms.verify_cms_code_directory(envelope, directory)
    assert result["state"] == "invalid"
    assert not result["cryptographic_signature_verified"]


def test_error_string_cannot_impersonate_child_exit(monkeypatch):
    envelope, directory = detached_fixture()

    def command(argv, **kwargs):
        if "-cmsout" in argv:
            return envelope
        raise ValueError("Command failed synthetic arbitrary text")

    monkeypatch.setattr(cms, "command", command)
    assert cms.verify_cms_code_directory(envelope, directory)["state"] == "not-run"


def test_detached_byte_match_does_not_promote_app_authenticity(monkeypatch):
    envelope, directory = detached_fixture()

    def command(argv, **kwargs):
        return envelope if "-cmsout" in argv else directory

    monkeypatch.setattr(cms, "command", command)
    result = cms.verify_cms_code_directory(envelope, directory)
    assert result["state"] == "verified" and result["cryptographic_signature_verified"]
    assert result["apple_signer_trust"] == "unverified"
    assert not result["certificate_chain_verified"]
    assert not result["app_authenticity_verified"]


def resource_archive(*, first=b"modified", first_missing=False, extra=False):
    raw = io.BytesIO()
    with zipfile.ZipFile(raw, "w") as archive:
        if not first_missing:
            archive.writestr("Payload/App.app/a-first", first)
        archive.writestr("Payload/App.app/z-later", b"later content")
        if extra:
            archive.writestr("Payload/App.app/unsealed", b"unexpected")
    entries = {
        "a-first": {"hash2": hashlib.sha256(b"original").digest()},
        "z-later": {"hash2": hashlib.sha256(b"later content").digest()},
    }
    envelope = plistlib.dumps({"files2": entries, "rules2": {"^.*": True}}, sort_keys=False)
    raw.seek(0)
    return zipfile.ZipFile(raw), envelope


@pytest.mark.parametrize("kind", ["modified", "missing", "unsealed"])
def test_known_modified_evidence_survives_later_byte_budget(monkeypatch, kind):
    archive, envelope = resource_archive(
        first=b"original" if kind == "unsealed" else b"modified",
        first_missing=kind == "missing",
        extra=kind == "unsealed",
    )
    monkeypatch.setattr(seals, "MAX_RESOURCE_BYTES", 10)
    with archive:
        result = seals.verify_resource_seal(archive, "Payload/App.app", "App", envelope)
    assert result["state"] == "modified"
    assert result["partial"] is True
    assert result["reason"] == "resource byte budget"
    assert not result["hashes_verified"] and not result["app_authenticity_verified"]
    assert (
        result[{"modified": "modified_files", "missing": "missing_files", "unsealed": "unsealed_files"}[kind]]
        == 1
    )


@pytest.mark.parametrize(
    "failure", [OSError("synthetic unreadable"), zipfile.BadZipFile("synthetic CRC failure")]
)
def test_known_modified_evidence_survives_later_unreadable_member(monkeypatch, failure):
    archive, envelope = resource_archive()
    original = archive.open

    def open_member(member, *args, **kwargs):
        if member.filename.endswith("z-later"):
            raise failure
        return original(member, *args, **kwargs)

    monkeypatch.setattr(archive, "open", open_member)
    with archive:
        result = seals.verify_resource_seal(archive, "Payload/App.app", "App", envelope)
    assert result["state"] == "modified" and result["modified_files"] == 1
    assert result["partial"] is True
    assert result["reason"] == "resource member unreadable"


def test_known_modified_evidence_survives_later_stream_budget(monkeypatch):
    archive, envelope = resource_archive()
    original = archive.open

    def open_member(member, *args, **kwargs):
        if member.filename.endswith("z-later"):
            return io.BytesIO(b"larger than the declared member size")
        return original(member, *args, **kwargs)

    monkeypatch.setattr(archive, "open", open_member)
    with archive:
        result = seals.verify_resource_seal(archive, "Payload/App.app", "App", envelope)
    assert result["state"] == "modified" and result["modified_files"] == 1
    assert result["partial"] is True and result["reason"] == "resource stream budget"


def test_budget_without_observed_modification_stays_partial(monkeypatch):
    archive, envelope = resource_archive(first=b"original")
    monkeypatch.setattr(seals, "MAX_RESOURCE_BYTES", 10)
    with archive:
        result = seals.verify_resource_seal(archive, "Payload/App.app", "App", envelope)
    assert result["state"] == "partial" and not result["modified_files"]
    assert not result["hashes_verified"] and not result["app_authenticity_verified"]


@pytest.mark.parametrize(
    "failure,state",
    [
        (CommandFailure("synthetic-verifier", 4), "invalid-or-unsupported"),
        (ValueError("Command failed untyped synthetic text"), "not-run"),
        (PermissionError("synthetic denied"), "not-run"),
    ],
)
def test_chain_failure_uses_child_exit_type_not_message_prefix(tmp_path, monkeypatch, failure, state):
    import base64

    anchor = b"synthetic canonical certificate bytes"

    def command(argv, **kwargs):
        if "x509" in argv:
            return anchor
        raise failure

    monkeypatch.setattr(cms, "command", command)
    result = cms._verify_chain(
        {"anchors": [{"der_base64": base64.b64encode(anchor).decode()}]},
        tmp_path / "signature.der",
        tmp_path / "directory.bin",
        b"synthetic directory",
        tmp_path,
        {},
    )
    assert result["chain_trust"] == state
    assert result["certificate_chain_verified"] is False
